definition.script:
pipeline {
  agent any
  options { timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '10')) }
  stages {
    stage('Refresh branch cache') {
      steps {
        sh '''
          set -euo pipefail
          export JENKINS_HOME=/var/jenkins_home
          export JENKINS_HOME_JOBS=/var/jenkins_home/jobs
          export BRANCH_CACHE_DIR=/var/jenkins_home/userContent/wealth-data/branches
          export WEALTH_UI_DATA=/var/jenkins_home/userContent/wealth-data
          export GITEE_FREEDOM=/gitee/wealth-freedom
          export GITEE_WEB=/gitee/wealth-freedom-web
          export GITEE_MALL=/gitee/wealth-ecommerce-web
          bash /jenkins-backup/scripts/refresh-branch-cache.sh
        '''
      }
    }
  }
    post {
    success { echo '分支与镜像缓存已更新。打开 /userContent/wealth/ 即可看到最新分支和下拉历史版本。' }
    failure { echo '失败时检查：github-ssh / 容器内 SSH 私钥、网络、/gitee 挂载' }
  }
}
